package app.vent.api

import kotlinx.serialization.Serializable

@Serializable data class ApiError(val code: String, val message: String, val requestId: String? = null)
@Serializable data class HealthResponse(val status: String)
@Serializable data class OtpRequest(val email: String)
@Serializable data class OtpVerifyRequest(val email: String, val code: String)
@Serializable data class OtpRequestResponse(val expiresInSeconds: Long = 600, val resendAfterSeconds: Long = 30)
@Serializable data class RefreshRequest(val refreshToken: String)
@Serializable data class AuthResponse(val accessToken: String, val refreshToken: String, val expiresInSeconds: Long)
@Serializable data class UserDto(val id: String, val name: String, val email: String, val roles: List<EventRoleDto>)
@Serializable data class EventRoleDto(val eventId: String, val role: String)
@Serializable data class EventDto(val id: String, val title: String, val startsAt: String, val endsAt: String, val seedArgb: String, val sessions: List<SessionDto> = emptyList())
@Serializable data class CreateEventRequest(val title: String, val startsAt: String, val endsAt: String, val seedArgb: String, val coverImageUrl: String? = null)
@Serializable data class UpdateSeedRequest(val seedArgb: String)
@Serializable data class HallDto(val id: String, val name: String, val width: Double, val height: Double, val seats: List<SeatDto>, val elements: List<HallElementDto>)
@Serializable data class SaveHallLayoutRequest(val width: Double, val height: Double, val seats: List<SeatDto>, val elements: List<HallElementDto>)
@Serializable data class SeatDto(val id: String, val label: String, val x: Double, val y: Double, val rotation: Double, val type: String, val state: String, val isMine: Boolean = false)
@Serializable data class HallElementDto(val kind: String, val label: String, val x: Double, val y: Double, val width: Double, val height: Double)
@Serializable data class SessionDto(val id: String, val eventId: String, val hallId: String, val title: String, val startsAt: String, val endsAt: String, val checkInOpensAt: String, val checkInClosesAt: String)
@Serializable data class CreateSessionRequest(val eventId: String, val hallId: String, val title: String, val startsAt: String, val endsAt: String, val checkInOpensAt: String, val checkInClosesAt: String)
@Serializable data class SeatSnapshotDto(val version: Long, val full: Boolean, val seats: List<SeatDto>)
@Serializable data class AssignmentPreviewRequest(val attendeeIds: List<String>)
@Serializable data class AssignmentPreviewDto(val previewId: String, val baseVersion: Long, val assignments: Map<String, String>, val unseated: List<String>)
@Serializable data class AssignmentCommitRequest(val previewId: String, val baseVersion: Long)
@Serializable data class CheckInRequest(val token: String, val deviceId: String, val clientTimestamp: String)
@Serializable data class ManualCheckInRequest(val bookingCode: String)
@Serializable data class CheckInResponse(val status: String, val seatLabel: String?, val pointsAwarded: Int)
@Serializable data class CheckInCodeDto(val token: String, val type: String, val expiresAt: String?)
@Serializable data class CreatePollRequest(val question: String, val options: List<String>)
@Serializable data class PollDto(val id: String, val sessionId: String, val question: String, val options: List<String>, val status: String)
@Serializable data class PollAnswerRequest(val optionIndex: Int)
@Serializable data class PollResultsDto(val pollId: String, val counts: List<Int>, val total: Int)
@Serializable data class LeaderboardEntryDto(val rank: Int, val displayName: String, val points: Int, val isCurrentUser: Boolean)
@Serializable data class QuestDto(val id: String, val type: String, val target: Int, val current: Int, val points: Int, val badge: BadgeDto, val completed: Boolean)
@Serializable data class CreateQuestRequest(val type: String, val target: Int, val points: Int, val badgeId: String)
@Serializable data class BadgeDto(val id: String, val name: String, val description: String)
@Serializable data class WrappedCardDto(val sessionsAttended: Int, val pollsAnswered: Int, val points: Int, val badges: List<BadgeDto>, val rank: Int)
@Serializable data class OccupancyDto(val sessionId: String, val capacity: Int, val assigned: Int, val checkedIn: Int, val noShows: Int)
